import Image from 'next/image';

// Intrinsic size of public/brand/apex-wordmark.png (a path, not a static import: CI has no next-env.d.ts image types).
const WIDTH = 886;
const HEIGHT = 206;

/**
 * The APEX wordmark: white heavy-italic letters with a red racing line through
 * the A. Owner-supplied (generated by the owner with Google Flow, 2026-11-05;
 * source public/brand/apex-wordmark.jpg), so no third-party licence record.
 * Transparent PNG, drawn for dark surfaces. Width follows the given height.
 */
export function ApexWordmark({
  className = '',
  alt = 'APEX',
  sizes,
  preload = false,
}: {
  className?: string;
  /** Empty string when a parent already names the link (e.g. aria-label). */
  alt?: string;
  sizes: string;
  preload?: boolean;
}) {
  return (
    <Image
      src="/brand/apex-wordmark.png"
      width={WIDTH}
      height={HEIGHT}
      alt={alt}
      sizes={sizes}
      preload={preload}
      draggable={false}
      className={['h-auto select-none', className].join(' ')}
    />
  );
}
